def transform(grid):
    n, m = len(grid), len(grid[0])
    objects = {}
    for r in range(n - 2):
        for c in range(m - 2):
            color = grid[r][c]
            if color:
                border = grid[r][c:c+3] + [grid[r+1][c], grid[r+1][c+2]] + grid[r+2][c:c+3]
                center = grid[r+1][c+1]
                if all(v == color for v in border) and center not in (0, color):
                    objects[color] = (center, r+1, c+1)
    gray = {(r,c) for r in range(n) for c in range(m) if grid[r][c] == 5}
    def gray_distance(r, c):
        return min(abs(r-a)+abs(c-b) for a,b in gray)
    ordered = sorted(objects, key=lambda x: gray_distance(objects[x][1], objects[x][2]))
    keep = set(ordered[:2])
    deleted = [x for x in objects if x not in keep]
    result = [row[:] for row in grid]
    for color, (_, r, c) in objects.items():
        if color not in keep:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    result[r+dr][c+dc] = 0
    for color in keep:
        _, r, c = objects[color]
        nearest = min(deleted, key=lambda x: abs(r-objects[x][1])+abs(c-objects[x][2]))
        result[r][c] = objects[nearest][0]
    return result
